// ─────────────────────────────────────────────────────────────────────
// Node: Parse & Authenticate Events          Mode: Run Once for All Items
// Repo: n8n-clay-webhook-enrichment-credit-guard · dhRobin Systems
// Purpose: authenticate each inbound HubSpot call, normalise both payload
// shapes (Workflow "Send a webhook" action and Webhooks API event arrays)
// into one item per HubSpot object, and drop secrets/headers from the data.
// ─────────────────────────────────────────────────────────────────────
const helpers = this.helpers;
let crypto = null;
try { crypto = require('crypto'); } catch (error) { crypto = null; }

const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // anything unrecognised falls back to the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};

const SANDBOX_MODE = flag('SANDBOX_MODE', true);
const DRY_RUN = flag('DRY_RUN', true);
const AUTH_MODE = env('WEBHOOK_AUTH_MODE', 'shared_secret').toLowerCase(); // shared_secret | hubspot_v3
const SECRET_HEADER = env('WEBHOOK_SECRET_HEADER', 'x-webhook-secret').toLowerCase();
const SANDBOX_FIXTURE_SECRET = 'sandbox-fictional-secret-not-for-production';
const CONFIGURED_SECRET = env('WEBHOOK_SHARED_SECRET', '');
const EXPECTED_SECRET = CONFIGURED_SECRET || (SANDBOX_MODE ? SANDBOX_FIXTURE_SECRET : '');
const ALWAYS_FETCH_RECORD = flag('ALWAYS_FETCH_RECORD', true);
const MAX_EVENTS = Math.max(1, num('MAX_EVENTS_PER_EXECUTION', 50));
const WATCHED_PROPERTIES = new Set(
  env('WATCHED_PROPERTY_CHANGES', 'domain,website,email').split(',').map((s) => s.trim().toLowerCase()).filter(Boolean)
);
const ACCEPTED_ACTIONS = new Set(['creation', 'propertychange']);

const newRunId = () => {
  try { if (crypto && crypto.randomUUID) return 'gate_' + crypto.randomUUID(); } catch (error) { /* fall through */ }
  return 'gate_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 10);
};

const lowerHeaders = (headers) => {
  const out = {};
  for (const [k, v] of Object.entries(headers || {})) out[String(k).toLowerCase()] = Array.isArray(v) ? String(v[0]) : String(v);
  return out;
};

// Constant-time comparison: hash both sides first so lengths never leak.
const safeEqual = (a, b) => {
  if (typeof a !== 'string' || typeof b !== 'string' || a === '' || b === '') return false;
  if (crypto) {
    const ha = crypto.createHash('sha256').update(a, 'utf8').digest();
    const hb = crypto.createHash('sha256').update(b, 'utf8').digest();
    return crypto.timingSafeEqual(ha, hb);
  }
  let diff = a.length ^ b.length;
  for (let i = 0; i < Math.max(a.length, b.length); i++) diff |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  return diff === 0;
};

async function readRawBody(item, index) {
  if (!item.binary || !item.binary.data) return null;
  try {
    const buffer = await helpers.getBinaryDataBuffer(index, 'data');
    return buffer.toString('utf8');
  } catch (error) {
    return null;
  }
}

async function authenticate(item, headers, rawBody) {
  if (AUTH_MODE === 'hubspot_v3') {
    const clientSecret = env('HUBSPOT_APP_CLIENT_SECRET', '');
    const publicUrl = env('HUBSPOT_WEBHOOK_PUBLIC_URL', '');
    if (!crypto || !clientSecret || !publicUrl) return { ok: false, method: 'hubspot_v3', reason: 'hubspot_v3_not_configured' };
    const provided = headers['x-hubspot-signature-v3'];
    const timestamp = headers['x-hubspot-request-timestamp'];
    if (!provided || !timestamp) return { ok: false, method: 'hubspot_v3', reason: 'hubspot_v3_headers_missing' };
    const skew = Math.abs(Date.now() - Number(timestamp));
    if (!Number.isFinite(skew) || skew > 5 * 60 * 1000) return { ok: false, method: 'hubspot_v3', reason: 'hubspot_v3_timestamp_out_of_window' };
    const body = rawBody !== null ? rawBody : JSON.stringify(item.json.body ?? '');
    const expected = crypto.createHmac('sha256', clientSecret).update(`POST${publicUrl}${body}${timestamp}`, 'utf8').digest('base64');
    return safeEqual(expected, String(provided))
      ? { ok: true, method: 'hubspot_v3' }
      : { ok: false, method: 'hubspot_v3', reason: 'hubspot_v3_signature_mismatch' };
  }
  if (!EXPECTED_SECRET) return { ok: false, method: 'shared_secret', reason: 'shared_secret_not_configured' };
  const provided = headers[SECRET_HEADER] || '';
  if (!safeEqual(provided, EXPECTED_SECRET)) return { ok: false, method: 'shared_secret', reason: 'shared_secret_mismatch' };
  return { ok: true, method: CONFIGURED_SECRET ? 'shared_secret' : 'sandbox_fixture_secret' };
}

// Accepts { prop: "value" } and legacy { prop: { value: "..." } } shapes.
const flattenProperties = (props) => {
  const out = {};
  if (!props || typeof props !== 'object' || Array.isArray(props)) return out;
  for (const [k, v] of Object.entries(props)) {
    let value = v;
    if (value && typeof value === 'object' && !Array.isArray(value) && 'value' in value) value = value.value;
    if (value === undefined) continue;
    out[String(k).toLowerCase()] = value === null ? null : typeof value === 'object' ? JSON.stringify(value) : String(value);
  }
  return out;
};

// Sandbox fixtures can say "SANDBOX_DAYS_AGO:12" so cooldown tests never go stale.
const resolveSandboxValues = (props) => {
  if (!SANDBOX_MODE) return props;
  for (const [k, v] of Object.entries(props)) {
    const match = typeof v === 'string' ? v.match(/^SANDBOX_DAYS_AGO:(\d{1,4})$/) : null;
    if (match) props[k] = new Date(Date.now() - Number(match[1]) * 86400000).toISOString();
  }
  return props;
};

const resolveObjectType = (raw, props = {}, query = {}) => {
  for (const candidate of [raw, query.objectType, query.object_type]) {
    const v = String(candidate || '').toLowerCase().trim();
    if (['company', 'companies', '0-2'].includes(v)) return 'company';
    if (['contact', 'contacts', '0-1'].includes(v)) return 'contact';
  }
  if (props.email) return 'contact';
  if (props.domain || props.website) return 'company';
  return null;
};

const toIso = (value, fallback) => {
  if (value === undefined || value === null || value === '') return fallback;
  const n = /^\d+$/.test(String(value)) ? Number(value) : Date.parse(String(value));
  return Number.isFinite(n) ? new Date(n).toISOString() : fallback;
};

const output = [];
const items = $input.all();

for (let index = 0; index < items.length; index++) {
  const item = items[index];
  const receivedAt = new Date().toISOString();
  const headers = lowerHeaders(item.json.headers);
  const query = item.json.query || {};
  const rawBody = await readRawBody(item, index);

  let body = item.json.body;
  if ((body === undefined || body === null || body === '' || (typeof body === 'object' && !Array.isArray(body) && Object.keys(body).length === 0)) && rawBody) {
    try { body = JSON.parse(rawBody); } catch (error) { body = null; }
  }
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (error) { /* left as string -> rejected below */ }
  }

  const runId = newRunId();
  const auth = await authenticate(item, headers, rawBody);
  const baseGate = {
    runId,
    receivedAt,
    sandboxMode: SANDBOX_MODE,
    dryRun: DRY_RUN,
    authOk: auth.ok,
    authMethod: auth.method,
    webhookCallIndex: index,
  };

  if (!auth.ok) {
    // Nothing from an unauthenticated body is carried forward.
    output.push({ json: { gate: { ...baseGate, payloadShape: 'not_parsed', eventType: null, rejectReason: auth.reason }, objectType: null, objectId: null, properties: null, needsFetch: false } });
    continue;
  }

  const events = [];
  if (Array.isArray(body)) {
    for (const ev of body) {
      const subscription = String((ev && ev.subscriptionType) || '');
      const [typePart, actionPart] = subscription.toLowerCase().split('.');
      const objectType = resolveObjectType(typePart);
      const base = {
        shape: 'hubspot_webhooks_api',
        objectType,
        objectId: ev && ev.objectId != null ? String(ev.objectId) : null,
        eventType: subscription || null,
        eventId: ev && ev.eventId != null ? String(ev.eventId) : null,
        occurredAt: toIso(ev && ev.occurredAt, receivedAt),
        properties: null,
      };
      if (!objectType || !ACCEPTED_ACTIONS.has(actionPart || '')) { events.push({ ...base, ignoreReason: 'unsupported_event_type' }); continue; }
      if (actionPart === 'propertychange' && !WATCHED_PROPERTIES.has(String(ev.propertyName || '').toLowerCase())) {
        events.push({ ...base, ignoreReason: 'unwatched_property_change' });
        continue;
      }
      events.push(base);
    }
  } else if (body && typeof body === 'object') {
    // "Include all properties" bodies nest under `properties`; customised bodies are flat key/value pairs.
    const propertySource = body.properties && typeof body.properties === 'object' ? body.properties : body;
    const props = resolveSandboxValues(flattenProperties(propertySource));
    for (const meta of ['objecttype', 'objectid', 'eventtype', 'eventid', 'occurredat', 'fixturenote']) delete props[meta];
    const rawId = body.objectId ?? body.hs_object_id ?? props.hs_object_id ?? body.vid ?? body.companyId ?? body.id;
    events.push({
      shape: 'hubspot_workflow_webhook',
      objectType: resolveObjectType(body.objectType, props, query),
      objectId: rawId != null ? String(rawId) : null,
      eventType: String(body.eventType || 'workflow.enrollment'),
      eventId: body.eventId != null ? String(body.eventId) : null,
      occurredAt: toIso(body.occurredAt, receivedAt),
      properties: Object.keys(props).length ? props : null,
    });
  } else {
    events.push({ shape: 'unknown', objectType: null, objectId: null, eventType: null, eventId: null, occurredAt: receivedAt, properties: null, rejectReason: 'empty_or_unparseable_body' });
  }

  if (events.length === 0) {
    events.push({ shape: 'hubspot_webhooks_api', objectType: null, objectId: null, eventType: null, eventId: null, occurredAt: receivedAt, properties: null, rejectReason: 'no_events_in_payload' });
  }

  const seen = new Set();
  let accepted = 0;
  for (const ev of events) {
    const key = `${ev.objectType}:${ev.objectId}`;
    if (!ev.ignoreReason && !ev.rejectReason) {
      if (ev.objectType && ev.objectId && seen.has(key)) ev.ignoreReason = 'duplicate_event_in_payload';
      else if (accepted >= MAX_EVENTS) ev.ignoreReason = 'max_events_per_execution_exceeded';
      else { seen.add(key); accepted++; }
    }
    const eligible = !ev.ignoreReason && !ev.rejectReason && !!ev.objectId && !!ev.objectType;
    output.push({
      json: {
        gate: {
          ...baseGate,
          payloadShape: ev.shape,
          eventType: ev.eventType,
          eventId: ev.eventId,
          occurredAt: ev.occurredAt,
          ignoreReason: ev.ignoreReason || null,
          rejectReason: ev.rejectReason || null,
        },
        objectType: ev.objectType,
        objectId: ev.objectId,
        properties: ev.properties,
        needsFetch: eligible && !SANDBOX_MODE && (ALWAYS_FETCH_RECORD || !ev.properties),
      },
    });
  }
}

return output;

// ─────────────────────────────────────────────────────────────────────
// Node: Merge Fetched Record                 Mode: Run Once for Each Item
// Merges the fresh HubSpot CRM record into the event item. CRM values win
// over inline webhook values unless the CRM value is empty.
// ─────────────────────────────────────────────────────────────────────
const original = $('Needs Record Fetch?').item.json;
const response = $json || {};
const statusCode = Number(response.statusCode || 0);

const errorText = (r) => {
  const e = r.error;
  const raw = (r.body && (r.body.message || r.body.category)) || (e && (e.message || e.description)) || (typeof e === 'string' ? e : '') || 'unknown_error';
  return String(raw)
    .replace(/Bearer\s+[A-Za-z0-9\-._~+\/]+=*/gi, 'Bearer [REDACTED]')
    .replace(/\bpat-[a-z0-9]{2,6}-[A-Za-z0-9-]{8,}\b/gi, '[REDACTED_HUBSPOT_TOKEN]')
    .slice(0, 300);
};

if (statusCode === 200 && response.body && response.body.properties) {
  const merged = { ...(original.properties || {}) };
  for (const [k, v] of Object.entries(response.body.properties)) {
    if (v !== null && v !== undefined && v !== '') merged[k.toLowerCase()] = String(v);
    else if (!(k.toLowerCase() in merged)) merged[k.toLowerCase()] = null;
  }
  return { json: { ...original, properties: merged, needsFetch: false, recordFetch: { ok: true, statusCode } } };
}

return {
  json: {
    ...original,
    needsFetch: false,
    recordFetch: {
      ok: false,
      statusCode: statusCode || null,
      category: response.body && response.body.category ? String(response.body.category) : null,
      message: errorText(response),
    },
  },
};

// ─────────────────────────────────────────────────────────────────────
// Node: Gatekeeper · Normalise, Filter & ICP Mode: Run Once for Each Item
// Normalises the root domain, blocks free/disposable/excluded domains,
// validates ICP fit, and checks record-level enrichment history.
// Output decision: candidate | rejected | disqualified | skipped | ignored
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback;
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback;
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback) => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

const SANDBOX_MODE = flag('SANDBOX_MODE', true);
const COOLDOWN_DAYS = Math.max(1, num('ENRICHMENT_COOLDOWN_DAYS', 90));
const DEDUPE_SCOPE = env('DEDUPE_SCOPE', 'domain').toLowerCase(); // domain | domain_and_object_type
const ICP_MIN_EMPLOYEES = num('ICP_MIN_EMPLOYEES', 20);
const ICP_MAX_EMPLOYEES = num('ICP_MAX_EMPLOYEES', 5000);
const ICP_ALLOW_UNKNOWN = flag('ICP_ALLOW_UNKNOWN_FIRMOGRAPHICS', true);

const normIndustry = (v) => String(v || '').trim().toUpperCase().replace(/&/g, 'AND').replace(/[^A-Z0-9]+/g, '_').replace(/^_+|_+$/g, '');
const COUNTRY_ALIASES = {
  us: 'united states', usa: 'united states', 'u.s.': 'united states', 'u.s.a.': 'united states', 'united states of america': 'united states',
  uk: 'united kingdom', gb: 'united kingdom', 'great britain': 'united kingdom', england: 'united kingdom', scotland: 'united kingdom', wales: 'united kingdom',
  ca: 'canada', au: 'australia', ie: 'ireland', de: 'germany', deutschland: 'germany', nl: 'netherlands', 'the netherlands': 'netherlands', holland: 'netherlands',
};
const normCountry = (v) => {
  const s = String(v || '').trim().toLowerCase();
  return COUNTRY_ALIASES[s] || s;
};

const ICP_INDUSTRIES = new Set(csv('ICP_INDUSTRIES', '').map(normIndustry));
const ICP_EXCLUDED_INDUSTRIES = new Set(
  csv('ICP_EXCLUDED_INDUSTRIES', 'GOVERNMENT_ADMINISTRATION,NON_PROFIT_ORGANIZATION_MANAGEMENT,EDUCATION_MANAGEMENT').map(normIndustry)
);
const ICP_COUNTRIES = new Set(
  csv('ICP_COUNTRIES', 'United States,Canada,United Kingdom,Ireland,Australia,Germany,Netherlands').map(normCountry)
);

const FREE_EMAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'yahoo.com', 'yahoo.co.uk', 'yahoo.co.in', 'yahoo.fr', 'yahoo.de', 'ymail.com', 'rocketmail.com',
  'hotmail.com', 'hotmail.co.uk', 'hotmail.fr', 'outlook.com', 'live.com', 'msn.com', 'aol.com', 'icloud.com', 'me.com', 'mac.com',
  'proton.me', 'protonmail.com', 'pm.me', 'gmx.com', 'gmx.de', 'gmx.net', 'web.de', 'mail.com', 'zoho.com', 'zohomail.com',
  'yandex.com', 'yandex.ru', 'mail.ru', 'inbox.ru', 'list.ru', 'bk.ru', 'qq.com', '163.com', '126.com', 'sina.com', 'naver.com',
  'daum.net', 'hanmail.net', 'rediffmail.com', 'fastmail.com', 'hey.com', 'tutanota.com', 'tuta.io', 't-online.de', 'orange.fr',
  'wanadoo.fr', 'free.fr', 'laposte.net', 'libero.it', 'virgilio.it', 'btinternet.com', 'sky.com', 'comcast.net', 'verizon.net',
  'att.net', 'sbcglobal.net', 'cox.net', 'bellsouth.net', 'earthlink.net', 'shaw.ca', 'rogers.com', 'sympatico.ca', 'bigpond.com',
  'optusnet.com.au',
]);
const DISPOSABLE_EMAIL_DOMAINS = new Set([
  'mailinator.com', 'guerrillamail.com', 'guerrillamail.info', 'sharklasers.com', '10minutemail.com', 'tempmail.com', 'temp-mail.org',
  'yopmail.com', 'trashmail.com', 'getnada.com', 'maildrop.cc', 'dispostable.com', 'throwawaymail.com', 'fakeinbox.com',
  'mintemail.com', 'mailnesia.com', 'emailondeck.com', 'moakt.com', 'tempr.email', 'burnermail.io', 'spamgourmet.com', 'mohmal.com',
  '33mail.com', 'mailcatch.com', 'inboxkitten.com', 'mytemp.email', 'tempail.com', 'emailfake.com', 'discard.email',
]);
const EXTRA_BLOCKED = new Set(csv('EXTRA_BLOCKED_DOMAINS', '').map((d) => d.toLowerCase()));
const EXCLUDED_DOMAINS = new Set(csv('EXCLUDED_DOMAINS', '').map((d) => d.toLowerCase())); // your own domain, customers, partners

// Compact list of two-label public suffixes. Extend via EXTRA_MULTI_PART_SUFFIXES.
const MULTI_PART_SUFFIXES = new Set([
  'co.uk', 'org.uk', 'ac.uk', 'gov.uk', 'ltd.uk', 'plc.uk', 'me.uk', 'com.au', 'net.au', 'org.au', 'co.nz', 'org.nz', 'co.jp',
  'ne.jp', 'or.jp', 'com.br', 'com.mx', 'com.ar', 'co.za', 'co.in', 'net.in', 'org.in', 'com.sg', 'com.my', 'com.hk', 'com.tr',
  'com.cn', 'co.kr', 'co.il', 'com.ph', 'com.pk', 'com.bd', 'co.id', 'com.vn', 'com.tw', 'com.ng', 'com.eg', 'com.sa', 'co.th',
  ...csv('EXTRA_MULTI_PART_SUFFIXES', '').map((s) => s.toLowerCase()),
]);

function rootDomainFrom(input) {
  if (input === null || input === undefined) return null;
  let s = String(input).trim().toLowerCase();
  if (!s) return null;
  if (s.includes('@')) s = s.split('@').pop();
  s = s.replace(/^[a-z][a-z0-9+.-]*:\/\//, '');
  s = s.split(/[\/?#\s]/)[0];
  s = s.replace(/^[^@]*@/, '').replace(/:\d+$/, '').replace(/\.+$/, '');
  const labels = s.split('.').filter(Boolean);
  if (labels.length < 2) return null;
  if (!labels.every((l) => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(l))) return null;
  const tld = labels[labels.length - 1];
  if (!/^(?:[a-z]{2,63}|xn--[a-z0-9-]{1,59})$/.test(tld)) return null;
  const lastTwo = labels.slice(-2).join('.');
  const take = MULTI_PART_SUFFIXES.has(lastTwo) && labels.length >= 3 ? 3 : 2;
  if (MULTI_PART_SUFFIXES.has(lastTwo) && labels.length < 3) return null; // bare public suffix
  return labels.slice(-take).join('.');
}

function parseEmployees(value) {
  if (value === null || value === undefined || value === '') return null;
  const s = String(value).replace(/,/g, '').trim();
  let m = s.match(/^(\d+)\s*\+$/);
  if (m) return { min: Number(m[1]), max: Infinity };
  m = s.match(/^(\d+)\s*(?:-|–|to)\s*(\d+)$/i);
  if (m) return { min: Number(m[1]), max: Number(m[2]) };
  if (/^\d+(?:\.\d+)?$/.test(s)) {
    const n = Math.round(Number(s));
    return { min: n, max: n };
  }
  return null;
}

const parseTime = (value) => {
  if (value === null || value === undefined || value === '') return null;
  const n = /^\d+$/.test(String(value)) ? Number(value) : Date.parse(String(value));
  return Number.isFinite(n) ? n : null;
};

const maskEmail = (email) => {
  const s = String(email || '');
  const at = s.indexOf('@');
  return at > 0 ? `${s[0]}***@${s.slice(at + 1).toLowerCase()}` : null;
};

const item = $json;
const props = item.properties || {};
const now = Date.now();
const cooldownMs = COOLDOWN_DAYS * 86400000;
const cutoffMs = now - cooldownMs;

const result = {
  rootDomain: null,
  domainSource: null,
  emailMasked: item.objectType === 'contact' ? maskEmail(props.email) : null,
  firmographics: null,
  decision: 'candidate',
  reasonCode: null,
  reasonDetail: null,
  writeEligible: false,
  needsDomainLookup: false,
  lookupRequest: null,
  cooldown: { days: COOLDOWN_DAYS, cutoffMs, cutoffIso: new Date(cutoffMs).toISOString() },
};
const finish = (decision, reasonCode, reasonDetail, writeEligible) => {
  result.decision = decision;
  result.reasonCode = reasonCode;
  result.reasonDetail = reasonDetail;
  result.writeEligible = !!writeEligible;
  return { json: { ...item, ...result } };
};

// 1 · Upstream gate results
if (!item.gate || !item.gate.authOk) return finish('rejected', 'unauthorized', (item.gate && item.gate.rejectReason) || 'auth_failed', false);
if (item.gate.rejectReason) return finish('rejected', item.gate.rejectReason, 'payload could not be processed', false);
if (item.gate.ignoreReason) return finish('ignored', item.gate.ignoreReason, item.gate.eventType || null, false);
if (!item.objectType || !item.objectId) return finish('rejected', 'missing_object_reference', 'objectType or objectId missing', false);

const idIsNumeric = /^\d+$/.test(String(item.objectId));
if (item.recordFetch && !item.recordFetch.ok) {
  if (item.recordFetch.statusCode === 404) return finish('rejected', 'record_not_found', 'HubSpot returned 404 for this object', false);
  return finish('skipped', 'record_fetch_failed', `HubSpot fetch failed (${item.recordFetch.statusCode || 'network'})`, false);
}
if (!item.properties) return finish('rejected', 'missing_record_properties', SANDBOX_MODE ? 'sandbox events need inline properties' : 'no properties available', idIsNumeric);

// 2 · Root-domain normalisation
const sources = item.objectType === 'contact'
  ? [['email', props.email], ['hs_email_domain', props.hs_email_domain]]
  : [['domain', props.domain], ['website', props.website]];
for (const [source, value] of sources) {
  const root = rootDomainFrom(value);
  if (root) { result.rootDomain = root; result.domainSource = source; break; }
}
if (!result.rootDomain) {
  const hadValue = sources.some(([, v]) => v !== null && v !== undefined && String(v).trim() !== '');
  return finish('rejected', hadValue ? 'invalid_root_domain' : 'missing_domain', `checked: ${sources.map(([s]) => s).join(', ')}`, idIsNumeric);
