const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};

const SANDBOX_MODE = flag('SANDBOX_MODE', true);
const DRY_RUN = flag('DRY_RUN', true);
const RING_SIZE = Math.max(0, num('AUDIT_RING_BUFFER_SIZE', 200));
const LOG_TO_STDOUT = flag('AUDIT_LOG_TO_STDOUT', true);

const KNOWN_SECRETS = ['HUBSPOT_ACCESS_TOKEN', 'CLAY_WEBHOOK_AUTH_TOKEN', 'WEBHOOK_SHARED_SECRET', 'HUBSPOT_APP_CLIENT_SECRET',
  'CLAY_TABLE_WEBHOOK_URL', 'CLAY_COMPANY_TABLE_WEBHOOK_URL', 'CLAY_CONTACT_TABLE_WEBHOOK_URL']
  .map((k) => env(k, '')).filter((v) => v.length >= 8);
const SECRET_KEY = /(authorization|token|secret|password|passwd|api[-_]?key|cookie|signature|x-clay-webhook-auth|client[-_]?secret)/i;
const redactString = (input) => {
  let s = String(input);
  for (const secret of KNOWN_SECRETS) s = s.split(secret).join('[REDACTED]');
  return s
    .replace(/Bearer\s+[A-Za-z0-9\-._~+\/]+=*/gi, 'Bearer [REDACTED]')
    .replace(/\bpat-[a-z0-9]{2,6}-[A-Za-z0-9-]{8,}\b/gi, '[REDACTED_HUBSPOT_TOKEN]')
    .replace(/https?:\/\/[^\s"']*clay\.com[^\s"']*/gi, '[REDACTED_CLAY_URL]')
    .replace(/\b([A-Za-z0-9._%+-])[A-Za-z0-9._%+-]*@([A-Za-z0-9.-]+\.[A-Za-z]{2,})\b/g, '$1***@$2')
    .slice(0, 1000);
};
const redact = (value, depth = 0) => {
  if (depth > 6) return '[TRUNCATED]';
  if (value === null || value === undefined) return value ?? null;
  if (typeof value === 'string') return redactString(value);
  if (Array.isArray(value)) return value.slice(0, 50).map((v) => redact(v, depth + 1));
  if (typeof value === 'object') {
    const out = {};
    for (const [k, v] of Object.entries(value)) out[k] = SECRET_KEY.test(k) ? '[REDACTED]' : redact(v, depth + 1);
    return out;
  }
  return value;
};

const item = $json;
const gate = item.gate || {};
const record = redact({
  auditVersion: 1,
  at: new Date().toISOString(),
  workflowId: $workflow.id || null,
  executionId: $execution.id || null,
  runId: gate.runId || null,
  mode: SANDBOX_MODE ? 'sandbox' : DRY_RUN ? 'dry_run' : 'live',
  auth: { ok: !!gate.authOk, method: gate.authMethod || null },
  event: { shape: gate.payloadShape || null, type: gate.eventType || null, id: gate.eventId || null, occurredAt: gate.occurredAt || null },
  objectType: item.objectType || null,
  objectId: item.objectId || null,
  rootDomain: item.rootDomain || null,
  domainSource: item.domainSource || null,
  emailMasked: item.emailMasked || null,
  firmographics: item.firmographics || null,
  decision: item.decision || null,
  status: item.status || null,
  reasonCode: item.reasonCode || null,
  reasonDetail: item.reasonDetail || null,
  domainLookup: item.domainLookup || null,
  credit: item.creditGuard
    ? {
        dayKey: item.creditGuard.dayKey,
        cost: item.creditGuard.cost,
        spentAfter: item.creditGuard.spentAfter,
        remaining: item.creditGuard.remaining,
        dailyBudget: item.creditGuard.dailyBudget,
        stateMode: item.creditGuard.stateMode,
      }
    : null,
  dispatch: item.dispatch
    ? { mode: item.dispatch.mode, ok: item.dispatch.ok, simulated: item.dispatch.simulated, httpCode: item.dispatch.httpCode || null, creditsRefunded: item.dispatch.creditsRefunded ?? null }
    : null,
  hubspot: { write: item.hubspotWrite || null, result: item.hubspotWriteResult || null, properties: item.hubspotProperties || null },
});

if (LOG_TO_STDOUT) {
  try { console.log(`[clay-credit-guard] ${JSON.stringify(record)}`); } catch (error) { /* logging is best effort */ }
}

if (RING_SIZE > 0 && !SANDBOX_MODE) {
  try {
    const store = $getWorkflowStaticData('global');
    if (!Array.isArray(store.clayCreditGuardAudit)) store.clayCreditGuardAudit = [];
    store.clayCreditGuardAudit.push(record);
    if (store.clayCreditGuardAudit.length > RING_SIZE) store.clayCreditGuardAudit.splice(0, store.clayCreditGuardAudit.length - RING_SIZE);
  } catch (error) { /* static data is unavailable in some manual runs */ }
}

return { json: record };

// ─────────────────────────────────────────────────────────────────────
// Node: Sanitized Error Handler              Mode: Run Once for All Items
// Fed by the Error Trigger when this workflow is its own Error Workflow.
// Drops stack traces, redacts secrets and emails, and emits a safe alert.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback;
  }
};
const KNOWN_SECRETS = ['HUBSPOT_ACCESS_TOKEN', 'CLAY_WEBHOOK_AUTH_TOKEN', 'WEBHOOK_SHARED_SECRET', 'HUBSPOT_APP_CLIENT_SECRET',
  'CLAY_TABLE_WEBHOOK_URL', 'CLAY_COMPANY_TABLE_WEBHOOK_URL', 'CLAY_CONTACT_TABLE_WEBHOOK_URL']
  .map((k) => env(k, '')).filter((v) => v.length >= 8);
const redactString = (input) => {
  let s = String(input ?? '');
  for (const secret of KNOWN_SECRETS) s = s.split(secret).join('[REDACTED]');
  return s
    .replace(/Bearer\s+[A-Za-z0-9\-._~+\/]+=*/gi, 'Bearer [REDACTED]')
    .replace(/\bpat-[a-z0-9]{2,6}-[A-Za-z0-9-]{8,}\b/gi, '[REDACTED_HUBSPOT_TOKEN]')
    .replace(/https?:\/\/[^\s"']*clay\.com[^\s"']*/gi, '[REDACTED_CLAY_URL]')
    .replace(/([?&](?:hapikey|api_key|apikey|token|key|secret)=)[^&\s"']+/gi, '$1[REDACTED]')
    .replace(/\b([A-Za-z0-9._%+-])[A-Za-z0-9._%+-]*@([A-Za-z0-9.-]+\.[A-Za-z]{2,})\b/g, '$1***@$2')
    .slice(0, 500);
};

return $input.all().map(({ json }) => {
  const execution = json.execution || {};
  const error = execution.error || json.trigger?.error || {};
  const alert = {
    alertType: 'clay_credit_guard_workflow_error',
    at: new Date().toISOString(),
    workflow: { id: json.workflow?.id || null, name: redactString(json.workflow?.name || '') },
    execution: { id: execution.id || null, mode: execution.mode || null, retryOf: execution.retryOf || null },
    lastNodeExecuted: execution.lastNodeExecuted || null,
    errorName: redactString(error.name || 'Error'),
    errorMessage: redactString(error.message || 'unknown error'),
    // Stack traces, request options and headers are deliberately not forwarded.
    nextStep: 'Open the execution in n8n (restricted access) and check the node named in lastNodeExecuted.',
  };
  try { console.error(`[clay-credit-guard:error] ${JSON.stringify(alert)}`); } catch (e) { /* best effort */ }
  return { json: alert };
});
